/**
 * Embeds prompts/careful-review.md into a TS module the server can import.
 * Pages Functions cannot load .md files directly, so this runs before dev,
 * build, typecheck and tests. Edit the markdown, not the generated file.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const source = join(root, 'prompts', 'careful-review.md')
const target = join(root, 'server', 'generated', 'careful-review.ts')

const markdown = readFileSync(source, 'utf8')

// Fail fast if an edit broke what the server relies on.
const required = ['## Системный промпт', '```text', '{framework}', '{crisis_contacts}', '## Протокол безопасности', '## Язык: запреты и замены']
const missing = required.filter((marker) => !markdown.includes(marker))
if (missing.length > 0) {
  console.error(`prompts/careful-review.md: не найдено ${missing.map((m) => `«${m}»`).join(', ')}`)
  process.exit(1)
}

mkdirSync(dirname(target), { recursive: true })
writeFileSync(
  target,
  `// GENERATED by scripts/build-prompts.mjs from prompts/careful-review.md. Do not edit.\n` +
    `export const CAREFUL_REVIEW_MD = ${JSON.stringify(markdown)}\n`,
)
console.log('prompts: server/generated/careful-review.ts updated')
